  const ivLength = 16; // AES block size is 16 bytes
  const keyLength = 32; // For AES-256

  // The docstring states "The provided key bytes is long enough (>= 64 bytes). Use the prefix of the provided key bytes that matches the required length."
  // This implies we should use the first `keyLength` bytes from the provided `key` buffer.
  // We will assume the caller ensures `key` is at least `keyLength` bytes.
